import{_ as n,C as r,o as t,c as i,a2 as a,b as l,w as s,a as d,E as c,a3 as h}from"./chunks/framework.Brv5O9VI.js";const x=JSON.parse('{"title":"14.8 Concurrency, Consistency & Distributed Systems","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.8-consistency-and-concurrency.md","filePath":"system-design/14.8-consistency-and-concurrency.md"}'),p={name:"system-design/14.8-consistency-and-concurrency.md"};function u(y,e,g,m,f,k){const o=r("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="_14-8-concurrency-consistency-distributed-systems" tabindex="-1">14.8 Concurrency, Consistency &amp; Distributed Systems <a class="header-anchor" href="#_14-8-concurrency-consistency-distributed-systems" aria-label="Permalink to &quot;14.8 Concurrency, Consistency &amp; Distributed Systems&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Concurrency manages how many tasks execute simultaneously without interfering with one another; consistency ensures that all clients see identical, accurate data regardless of which server or node answers their query.</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How THIS Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How THIS Project Uses It&quot;">​</a></h2><ul><li><strong>Thread Concurrency Model</strong>: Uvicorn runs an asynchronous <code>asyncio</code> event loop. Because the route handlers (<code>chat_endpoint</code> and <code>export_audit</code>) are defined as standard <code>def</code> functions rather than <code>async def</code> ([<code>app.py:L74,L141</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L74)), FastAPI automatically offloads them to an internal threadpool (<code>anyio</code>), preventing CPU-bound vector math from starving the event loop.</li><li><strong>Data Consistency Model</strong>: <strong>Strict Read-Only Consistency</strong>. The vector index and corpus are static, immutable files loaded once at boot. Because no concurrent write mutations take place during runtime, the system is fundamentally immune to race conditions, deadlocks, and dirty reads.</li></ul>',6)),(t(),l(h,null,{default:s(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Client1%5B%22Client%20Request%20A%22%5D%20--%3E%20EventLoop%5B%22Uvicorn%20Async%20Event%20Loop%22%5D%0A%20%20%20%20Client2%5B%22Client%20Request%20B%22%5D%20--%3E%20EventLoop%0A%20%20%20%20%0A%20%20%20%20EventLoop%20--%3E%7COffload%20def%20handler%7C%20ThreadPool%5B%22FastAPI%20Worker%20ThreadPool%22%5D%0A%20%20%20%20%0A%20%20%20%20ThreadPool%20--%3E%20Thread1%5B%22Thread%201%3A%20ONNX%20Embed%20%2B%20FAISS%20Read%22%5D%0A%20%20%20%20ThreadPool%20--%3E%20Thread2%5B%22Thread%202%3A%20ONNX%20Embed%20%2B%20FAISS%20Read%22%5D%0A%20%20%20%20%0A%20%20%20%20Thread1%20--%3E%7CLock-Free%20Concurrent%20Read%7C%20Memory%5B%22In-Memory%20FAISS%20Index%20(Read-Only)%22%5D%0A%20%20%20%20Thread2%20--%3E%7CLock-Free%20Concurrent%20Read%7C%20Memory%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_3-comparison-with-concurrency-models" tabindex="-1">3. Comparison with Concurrency Models <a class="header-anchor" href="#_3-comparison-with-concurrency-models" aria-label="Permalink to &quot;3. Comparison with Concurrency Models&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Concurrency Strategy</th><th style="text-align:left;">Memory Isolation</th><th style="text-align:left;">GIL Impact</th><th style="text-align:left;">Thread Overhead</th><th style="text-align:left;">Race Condition Risk</th><th style="text-align:left;">Fit for This Engine</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FastAPI ThreadPool (AnyIO)</strong> (Used)</td><td style="text-align:left;">Shared Process Memory</td><td style="text-align:left;">Bound by GIL for pure Python</td><td style="text-align:left;">Moderate (~100 threads)</td><td style="text-align:left;"><strong>Zero (Read-only data)</strong></td><td style="text-align:left;"><strong>Optimal</strong></td></tr><tr><td style="text-align:left;"><strong>ProcessPoolExecutor</strong></td><td style="text-align:left;">Separate Address Space</td><td style="text-align:left;">Completely bypasses GIL</td><td style="text-align:left;">High (Duplicate model memory)</td><td style="text-align:left;">Zero</td><td style="text-align:left;">Good for multi-core saturation</td></tr><tr><td style="text-align:left;"><strong>Go Goroutines</strong></td><td style="text-align:left;">Shared Heap + Channels</td><td style="text-align:left;">No GIL</td><td style="text-align:left;">Extremely Low (2 KB stack)</td><td style="text-align:left;">Low</td><td style="text-align:left;">Language switch required</td></tr><tr><td style="text-align:left;"><strong>Node.js Worker Threads</strong></td><td style="text-align:left;">Isolated Contexts</td><td style="text-align:left;">Single-threaded event loop</td><td style="text-align:left;">Moderate</td><td style="text-align:left;">Low</td><td style="text-align:left;">Poor ML ecosystem</td></tr></tbody></table><hr><h2 id="_4-trade-offs-accepted" tabindex="-1">4. Trade-offs Accepted <a class="header-anchor" href="#_4-trade-offs-accepted" aria-label="Permalink to &quot;4. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>Python GIL (Global Interpreter Lock)</strong>: While C++ FAISS code releases the GIL during search, pure Python execution (Pydantic parsing, guardrail regex, and gap engine loops) is serialized across threads within a single Python process.</li></ul><hr><h2 id="_5-what-breaks-at-scale" tabindex="-1">5. What Breaks at Scale <a class="header-anchor" href="#_5-what-breaks-at-scale" aria-label="Permalink to &quot;5. What Breaks at Scale&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: Handled smoothly by thread pool concurrency.</li><li><strong>At 100x Load</strong>: GIL lock contention begins degrading throughput when multiple threads compete for CPU time on a single process.</li><li><strong>At 1000x Load</strong>: Requires running multiple independent OS worker processes via Uvicorn <code>--workers N</code> or Docker container replicas to saturate all CPU cores across nodes.</li></ul><hr><h2 id="_6-how-a-senior-engineer-would-improve-it" tabindex="-1">6. How a Senior Engineer Would Improve It <a class="header-anchor" href="#_6-how-a-senior-engineer-would-improve-it" aria-label="Permalink to &quot;6. How a Senior Engineer Would Improve It&quot;">​</a></h2><p>Launch Uvicorn with a worker process per CPU core:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uvicorn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app:app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nproc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Each worker process operates its own independent Python runtime, completely bypassing the GIL and scaling throughput linearly with CPU cores.</p><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;Because our application is strictly read-only during runtime, we achieve lock-free concurrent vector searches across threads without race condition risks. FastAPI automatically offloads our synchronous handlers to background threadpools so the event loop stays responsive, and running Uvicorn with multiple worker processes completely bypasses the Python GIL to scale linearly across CPU cores.&quot;</p></blockquote>',17))])}const b=n(p,[["render",u]]);export{x as __pageData,b as default};
